import { AbstractColDef } from "ag-grid-community/dist/types/core/entities/colDef";
import { IEventEmitter } from "ag-grid-community/dist/types/core/interfaces/iEventEmitter";
import { ColumnGroup, ColumnGroupShowType } from "ag-grid-community/dist/types/core/entities/columnGroup";
import { ColumnPinnedType } from "ag-grid-community/dist/types/core/entities/column";
import { BrandedType } from "ag-grid-community/dist/types/core/utils";
export type HeaderColumnId = BrandedType<string, 'HeaderColumnId'>;
export interface IHeaderColumn<TValue = any> extends IEventEmitter {
    getUniqueId(): HeaderColumnId;
    getActualWidth(): number;
    getMinWidth(): number | null | undefined;
    getLeft(): number | null;
    getOldLeft(): number | null;
    getDefinition(): AbstractColDef<any, TValue> | null;
    getColumnGroupShow(): ColumnGroupShowType | undefined;
    getParent(): IHeaderColumn;
    isResizable(): boolean;
    setParent(parent: ColumnGroup | null): void;
    isEmptyGroup(): boolean;
    isMoving(): boolean;
    getPinned(): ColumnPinnedType;
}
